-- ============================================================
-- SEED: 20 mock customers for testco@gmail.com (auto-resolve user_id)
-- Run this directly in Supabase SQL editor — no manual UUID lookup
-- ============================================================

do $$
declare
  v_user_id uuid;
begin
  select id into v_user_id
  from auth.users
  where email = 'testco@gmail.com';

  if v_user_id is null then
    raise exception 'No auth user found with email testco@gmail.com';
  end if;

  on conflict do nothing;
end $$;

-- Verify count
select count(*) as total_customers
from customers c
join auth.users u on u.id = c.user_id
where u.email = 'testco@gmail.com';
